//! The built-in framework rule table.
//!
//! Ranked by the inventory in §4 of the design: popularity from the
//! Stack Overflow 2025 Developer Survey plus registry download counts,
//! not by how easy each was to implement.
//!
//! Two things make this table honest rather than merely large.
//!
//! **Every rule is gated on detection.** `detect` lists import prefixes
//! that prove the framework is actually in use. Without that gate, a
//! rule matching the verb `get` would claim every `cache.get` in the
//! repository as an HTTP route. Detection is what lets the verb lists
//! stay short and shared — one `receiver.VERB(string, callable)` matcher
//! covers Gin, Echo, Fiber and Chi at once precisely because each is
//! gated on its own import.
//!
//! **Frameworks cgg cannot enumerate are still listed.** A rule with no
//! matchers contributes no entry nodes but does contribute a line to the
//! coverage table saying so. That is the difference between "cgg found
//! 3 routes" and "cgg found 3 routes and cannot read `config/routes.rb`,
//! where the other 300 live".

use super::{FrameworkRule, TrustKind};

/// Compact literal form of a rule. Expanded into owned [`FrameworkRule`]
/// values once, on first use.
#[derive(Debug)]
pub struct RuleSpec {
    pub id: &'static str,
    pub language: &'static str,
    pub kind: TrustKind,
    pub detect: &'static [&'static str],
    pub detect_paths: &'static [&'static str],
    /// Call names whose mere presence proves the framework — the escape
    /// hatch for ecosystems with no import records at all (WordPress).
    pub detect_calls: &'static [&'static str],
    pub attributes: &'static [&'static str],
    pub registrars: &'static [&'static str],
    pub base_types: &'static [&'static str],
    pub methods: &'static [&'static str],
    /// Whether a string argument may name the handler — shape E.
    pub string_targets: bool,
    pub node: bool,
    /// Stated when the rule cannot enumerate entries, for the coverage
    /// table's "seen, no rules" column.
    pub gap: &'static str,
    /// Class-field type names whose assignment creates `on_<field>`
    /// observer callbacks (e.g. Kivy's `StringProperty`).  When
    /// non-empty, framework detection checks `FileFacts::class_fields`
    /// for a matching type and tags the corresponding `on_<field>`
    /// method as a lifecycle root.
    pub observer_types: &'static [&'static str],
    /// Use the enclosing-owner lookup for value-ref handler resolution.
    ///
    /// When true, `self.bind(on_x=self.handler)` prefers the handler
    /// on the same class as the bind() call.  Off by default because
    /// the lookup leaks into every language — in Clojure the enclosing
    /// "owner" is the namespace, so any `(get m id)` inside a defn
    /// would bind to the namespace's `id`.
    ///
    /// When set, the framework matcher prefers value-ref handlers on the
    /// same type as the registrar call (e.g. `self.bind(on_x=self.handler)`
    /// resolves to the handler on the enclosing class, not a same-named
    /// method elsewhere). Opt-in; currently only the `kivy` rule sets this.
    pub handler_on_enclosing_owner: bool,
}

const NONE: &[&str] = &[];

/// libFuzzer's engine-called entry points (`LLVMFuzzerTestOneInput` and
/// its optional hooks), C ABI in both C and C++.
const LIBFUZZER_HOOKS: &[&str] = &[
    "LLVMFuzzerTestOneInput",
    "LLVMFuzzerInitialize",
    "LLVMFuzzerCustomMutator",
    "LLVMFuzzerCustomCrossOver",
];

/// HTTP verbs, lowercase. Matching is case-insensitive so this one list
/// covers Go's `GET`, Rails' `get` and NestJS's `Get`.
const HTTP_VERBS: &[&str] = &[
    "get", "post", "put", "delete", "patch", "head", "options", "trace", "connect",
];

/// Ruby class-body DSL calls whose symbol arguments name methods of the
/// class, read as value references when the run records reference sites
/// (`validate :check_dates`, ActiveModel). Not registrar verbs: a
/// registrar captures every call of the verb, and `validate(x, y)` is an
/// ordinary method call far more often than the DSL.
pub const RUBY_SYMBOL_CALLBACK_VERBS: &[&str] = &["validate"];

/// Clojure libraries whose `defn`/`defn-`/`defmethod` macros define a
/// function under a schema (`(s/defn f :- Int [x :- Int] …)`): a head
/// qualified by an alias of one of these namespaces is a definition. A
/// namespace of the tree that itself defines such a macro qualifies too
/// (`cgg_lang::plugins::clojure::settle_defn_macros`).
pub const CLOJURE_DEFN_MACRO_NAMESPACES: &[&str] =
    &["clojure.core", "schema.core", "malli.experimental"];

/// Clojure macros that re-export another namespace's vars under the
/// calling namespace (potemkin's `(import-vars [a.b f g])`): a `defn`
/// macro re-exported this way qualifies its new namespace too.
pub const CLOJURE_REEXPORT_FORMS: &[&str] = &["import-vars"];

/// The definition macros a [`CLOJURE_DEFN_MACRO_NAMESPACES`] namespace (or
/// a tree namespace defining one) provides.
pub const CLOJURE_DEFN_MACRO_NAMES: &[&str] = &["defn", "defn-", "defmethod"];

/// File names the gRPC / Connect code generators write: their classes
/// are client stubs, server base classes and message types, never the
/// implementation of an rpc (`descriptor::link_descriptors`). A marker
/// ending in `.` matches anywhere in the file name (`.pb.` covers
/// `x.pb.go`, `x_grpc.pb.go`, `x.pb.cc`, `x.pb.h`), any other at its end.
pub const GRPC_GENERATED_FILE_MARKERS: &[&str] = &[
    ".pb.",
    "_pb2.py",
    "_pb2_grpc.py",
    "_pb2.pyi",
    "_pb2_grpc.pyi",
    ".connect.go",
    "_pb.js",
    "_pb.d.ts",
    "_grpc_pb.js",
    "_grpc_pb.d.ts",
    "Grpc.java",
    "Grpc.cs",
    "GrpcKt.kt",
];

/// Owner-type name prefixes and suffixes (compared lowercased) of the
/// generated or test classes that carry an rpc's name without serving
/// it: `UnimplementedGreeterServer`, `MockGreeterClient`, `GreeterClient`,
/// `GreeterBlockingStub`.
pub const RPC_STUB_OWNER_PREFIXES: &[&str] = &["unimplemented", "mock"];
pub const RPC_STUB_OWNER_SUFFIXES: &[&str] = &["client", "stub"];

/// Web-framework traits whose method the framework calls on a handler's
/// return value: axum/poem `IntoResponse`, actix-web/rocket `Responder`.
pub const RESPONSE_TRAITS: &[&str] = &["IntoResponse", "Responder"];

/// Generic wrappers that convert themselves (`Json<T>` serializes `T`; it
/// never calls `T`'s own conversion) or that are not responses at all.
/// A type named only inside one of these is not handed to the framework.
/// The web-framework response bodies are listed with the std containers
/// that are never responses either.
pub const SELF_CONVERTING_WRAPPERS: &[&str] = &[
    "Json", "Html", "Form", "Xml", "Sse", "Protobuf", "Msgpack", "Cbor", "Vec",
    "HashMap", "BTreeMap", "HashSet", "Box", "Arc", "Rc", "Cow",
];

