/// Expand the compact table into owned rules.
pub fn builtin() -> Vec<FrameworkRule> {
    SPECS
        .iter()
        .map(|s| FrameworkRule {
            id: s.id.to_string(),
            language: s.language.to_string(),
            kind: s.kind,
            detect: s.detect.iter().map(|x| x.to_string()).collect(),
            detect_paths: s.detect_paths.iter().map(|x| x.to_string()).collect(),
            attributes: s.attributes.iter().map(|x| x.to_string()).collect(),
            registrars: s.registrars.iter().map(|x| x.to_string()).collect(),
            base_types: s.base_types.iter().map(|x| x.to_string()).collect(),
            methods: s.methods.iter().map(|x| x.to_string()).collect(),
            string_targets: s.string_targets,
            node: s.node,
            observer_types: s.observer_types.iter().map(|x| x.to_string()).collect(),
            handler_on_enclosing_owner: s.handler_on_enclosing_owner,
        })
        .collect()
}

/// Identifiers that mark a *file* as the thing the framework enters,
/// rather than marking a callable inside it.
///
/// Shape F normally reads the spawn site: `new Worker('./jobs/x.js')`
/// names the module, and the entry is minted on the far end. That only
/// works when the path is a literal. Real code writes
/// `new Worker(workerFile)` with a variable, and the worker file is
/// then referenced from nowhere — the whole module reads as dead.
///
/// A worker module identifies itself, though: it imports
/// `worker_threads` and talks to `parentPort`. That pair is the receive
/// side of the channel and appears in no spawner, so it is a precise
/// marker for "this file is entered as a thread".
///
/// Kept out of [`FrameworkRule`] for the same reason as
/// [`detect_calls_for`]: it selects a *file*, not a callable, so no
/// matcher field fits it and a user-authored rule has no business
/// declaring one.
pub fn self_module_markers_for(id: &str, language: &str) -> &'static [&'static str] {
    match (id, language) {
        ("worker-threads", "javascript") | ("worker-threads", "typescript") => {
            &["parentPort", "workerData"]
        }
        _ => NONE,
    }
}

/// Visibility keywords that make a callable an entry point on their own.
///
/// Solidity has no framework to detect: the *language* declares the trust
/// boundary. A `public` or `external` function is callable by any address
/// on the chain, and that is true whether or not the contract imports
/// anything. No other matcher can express this — `attributes`,
/// `registrars` and `base_types` all describe things written *around* a
/// definition, while this is a keyword *on* it.
///
/// Kept out of [`FrameworkRule`] alongside [`detect_calls_for`]: it is a
/// property of a language, not a rule a user should be authoring.
pub fn visibility_entries_for(id: &str, language: &str) -> &'static [&'static str] {
    match (id, language) {
        ("solidity-public", "solidity") => &["public", "external"],
        _ => NONE,
    }
}

/// An attribute whose *arguments* name the members a framework invokes.
///
/// `@MethodSource("words")`, `[TestCaseSource(nameof(Cases))]` and
/// `[MemberData(nameof(Data), MemberType = typeof(Shared))]` sit on a
/// test, but what they make live is the member they name — which no
/// call in source ever reaches. The matcher reads every string literal
/// and `nameof(…)` argument as a member name (`Class#member` and
/// `T.member` qualify the owner), and a `typeof(T)` / `T.class`
/// argument as the owning type.
///
/// Kept out of [`FrameworkRule`] alongside [`visibility_entries_for`]:
/// it is a property of a built-in framework's attribute grammar, not a
/// matcher a user-authored rule should be declaring.
#[derive(Debug)]
pub struct MemberSource {
    /// Attribute key, compared like [`RuleSpec::attributes`].
    pub attribute: &'static str,
    /// With no member named at all, the framework looks up a member
    /// with the annotated method's own name (JUnit's bare `@MethodSource`).
    pub default_self: bool,
    /// With a type named but no member, the members of that type the
    /// framework invokes (`[ClassData(typeof(T))]` enumerates `T`).
    pub type_members: &'static [&'static str],
    /// Named elements whose string value names a member
    /// (`@CircuitBreaker(name = "b", fallbackMethod = "recover")`). When
    /// any are listed, a positional string is not a member name (Sentinel's
    /// `@SentinelResource("res")` names a resource), though a positional
    /// type literal still names the owner.
    pub named: &'static [NamedElement],
}

/// One named element of a [`MemberSource`] attribute, and the element that
/// may name the type declaring that member (`blockHandler` and
/// `blockHandlerClass = T.class`; empty when the member is always the
/// annotated method's class's own).
#[derive(Debug)]
pub struct NamedElement {
    pub element: &'static str,
    pub class_element: &'static str,
}

/// `fallbackMethod = "m"`: the element of Resilience4j's, Hystrix's and
/// MicroProfile's fallback-naming annotations.
const FALLBACK_METHOD: &[NamedElement] = &[NamedElement {
    element: "fallbackMethod",
    class_element: "",
}];

/// The member-naming attributes of one built-in rule.
pub fn member_sources_for(id: &str, language: &str) -> &'static [MemberSource] {
    match (id, language) {
        ("junit-sources", "java" | "kotlin") => &[
            MemberSource {
                attribute: "MethodSource",
                default_self: true,
                type_members: NONE,
                named: &[],
            },
            MemberSource {
                attribute: "ArgumentsSource",
                default_self: false,
                type_members: &["provideArguments"],
                named: &[],
            },
        ],
        // A fallback or recovery method the fault-tolerance library looks
        // up by name on the annotated method's class (or the class a
        // `…Class = T.class` element names).
        ("fault-tolerance", "java" | "kotlin") => &[
            MemberSource {
                attribute: "CircuitBreaker",
                default_self: false,
                type_members: NONE,
                named: FALLBACK_METHOD,
            },
            MemberSource {
                attribute: "Retry",
                default_self: false,
                type_members: NONE,
                named: FALLBACK_METHOD,
            },
            MemberSource {
                attribute: "RateLimiter",
                default_self: false,
                type_members: NONE,
                named: FALLBACK_METHOD,
            },
            MemberSource {
                attribute: "Bulkhead",
                default_self: false,
                type_members: NONE,
                named: FALLBACK_METHOD,
            },
            MemberSource {
                attribute: "TimeLimiter",
                default_self: false,
                type_members: NONE,
                named: FALLBACK_METHOD,
            },
            MemberSource {
                attribute: "HystrixCommand",
                default_self: false,
                type_members: NONE,
                named: FALLBACK_METHOD,
            },
            // MicroProfile: `@Fallback(fallbackMethod = "m")`, or
            // `@Fallback(H.class)` whose `handle` the container calls.
            MemberSource {
                attribute: "Fallback",
                default_self: false,
                type_members: &["handle"],
                named: FALLBACK_METHOD,
            },
            MemberSource {
                attribute: "SentinelResource",
                default_self: false,
                type_members: NONE,
                named: &[
                    NamedElement {
                        element: "blockHandler",
                        class_element: "blockHandlerClass",
                    },
                    NamedElement {
                        element: "fallback",
                        class_element: "fallbackClass",
                    },
                    NamedElement {
                        element: "defaultFallback",
                        class_element: "fallbackClass",
                    },
                ],
            },
            // Spring Retry: `@Retryable(recover = "m")`; an unnamed
            // `@Recover` method is a row attribute.
            MemberSource {
                attribute: "Retryable",
                default_self: false,
                type_members: NONE,
                named: &[NamedElement {
                    element: "recover",
                    class_element: "",
                }],
            },
        ],
        ("nunit-runner", "csharp") => &[
            MemberSource {
                attribute: "TestCaseSource",
                default_self: false,
                type_members: &["GetEnumerator"],
                named: &[],
            },
            MemberSource {
                attribute: "ValueSource",
                default_self: false,
                type_members: &["GetEnumerator"],
                named: &[],
            },
        ],
        ("xunit-data", "csharp") => &[
            MemberSource {
                attribute: "MemberData",
                default_self: false,
                type_members: NONE,
                named: &[],
            },
            MemberSource {
                attribute: "ClassData",
                default_self: false,
                type_members: &["GetEnumerator"],
                named: &[],
            },
        ],
        _ => &[],
    }
}

/// Attributes on a *container* that hand every member to the framework.
///
/// `#[pymethods] impl Foo { fn __next__(..) }` exports `__next__` to
/// Python although the method itself carries no attribute; an
/// async-graphql `#[Object] impl Query` makes each method a field the
/// executor resolves. Compared like [`RuleSpec::attributes`] (whole key
/// or last path segment, case-insensitive). Read from
/// `FileFacts::attributed_containers`, so only plugins that record
/// container attributes (Rust `impl` blocks) contribute.
pub fn container_attributes_for(id: &str, language: &str) -> &'static [&'static str] {
    match (id, language) {
        // Every method of the block crosses: PyO3 exports each fn of a
        // `#[pymethods]` block, uniffi each of an exported impl. (A
        // `#[napi]`/`#[wasm_bindgen]` impl exports only members that
        // carry the attribute themselves or are `pub`, so it is not here.)
        ("ffi-export", "rust") => &["pymethods", "uniffi::export"],
        ("async-graphql", "rust") => &[
            "Object",
            "ComplexObject",
            "Subscription",
            "MergedObject",
            "Interface",
        ],
        ("juniper", "rust") => &[
            "graphql_object",
            "graphql_subscription",
            "graphql_interface",
        ],
        // `#[tool_handler] impl ServerHandler for S`: the MCP runtime calls
        // the handler methods. (`#[tool_router]` blocks are not here: only
        // their `#[tool]` members are tools.)
        ("rmcp", "rust") => &["tool_handler", "prompt_handler"],
        // `#[interface] impl Greeter`: the D-Bus daemon calls every method
        // (and `#[zbus(property)]` accessor) for other processes. Signal
        // members are skipped (`container_member_skipped`).
        ("zbus", "rust") => &["interface", "zbus::interface", "dbus_interface"],
        _ => NONE,
    }
}

/// Whether a test harness injects its block verbs as globals, and how
/// strongly a tree's evidence for it names the runner.
///
/// A test file that imports a harness (`from 'vitest'`,
/// `@playwright/test`, `node:test`) belongs to that harness. One that
/// imports none calls `describe`/`it` as globals, which only Jest, Mocha
/// and Vitest (`globals: true`) provide: such a file belongs to the
/// globals harness the tree's config files or imports detect most often
/// (rank 2), or, with none detected, to the anonymous `js-test-globals`
/// rule (rank 1). Rank 0: the harness is reached only by import.
pub fn harness_globals_rank(id: &str, language: &str) -> u8 {
    match (id, language) {
        ("jest" | "mocha" | "vitest", "javascript" | "typescript") => 2,
        ("js-test-globals", "javascript" | "typescript") => 1,
        _ => 0,
    }
}

/// Languages whose annotations are names a file imports. A rule's
/// attribute matches there only in a file that carries the rule's import
/// evidence, or where the annotation is written fully qualified under one
/// of its `detect` prefixes: `@Scheduled` on a member of a file that
/// imports nothing from Spring is an annotation of its own package.
///
/// Python, JavaScript and TypeScript decorators are names too (`@tool`,
/// `@app.task`), and their keys are generic enough that one framework's
/// decorator matched another's rule wherever the tree used both (an
/// `@mcp.tool` took an entry of every agent framework with a `tool`
/// decorator). There a decorator whose head the file imports from one of
/// the tree's own modules (`from .celeryconf import app`) counts when
/// that module carries the evidence.
pub const IMPORT_SCOPED_ATTRIBUTES: &[&str] =
    &["java", "kotlin", "python", "javascript", "typescript"];

/// Languages in which a file names what it uses through its own imports,
/// so a bare registrar call (`tool({…})`, axum's `get(h)`) and a base type
/// (`extends HttpServlet`, `impl Tool for X`) are a framework's only in a
/// file carrying that framework's evidence: it imports a `detect` prefix,
/// writes the name qualified under one, or (Python, JS/TS) imports the
/// name from one of the tree's own modules that does. A base type found
/// up the inheritance chain is judged in the file that declares it.
///
/// Not Ruby (autoloading: no file imports what it uses), C# (implicit and
/// `global using`s state a file's namespaces outside it), Dart (a `part`
/// file shares its library's imports), Scala (package-object and
/// enclosing-package imports), PHP (a class of the file's own namespace
/// or the global one needs no `use`), nor the languages whose include or
/// load is transitive (C, C++, Lua, Perl, Elixir, Clojure).
pub const FILE_SCOPED_EVIDENCE: &[&str] = &[
    "python",
    "javascript",
    "typescript",
    "java",
    "kotlin",
    "go",
    "rust",
    "swift",
];

/// Languages in which every member of a test-harness base class (a
/// `unittest.TestCase`, PHPUnit `TestCase`, `Minitest::Test` subclass) is
/// a test root, not only its `test*` cases. Their test helpers are called
/// as `self.helper()` / `$this->helper()` from subclasses in other files,
/// an inherited dynamic call the resolver often cannot bind; before WS18
/// every member was a (production) root, and rooting them as test code
/// keeps those helpers out of the report without making what they reach
/// production-live. Statically typed languages (Java, Swift) bind such
/// calls and keep their unused helpers reportable.
pub const TEST_CLASS_MEMBERS_ARE_ROOTS: &[&str] = &["python", "php", "ruby"];

/// Markup kinds whose event bindings (`FileFacts::markup_bindings`) are
/// this rule's entries: `xaml` (`Click="OnSave"`), `razor`
/// (`@onclick="Save"`), `tscn` (a Godot scene's `[connection]`). The event
/// is the entry's key, so one node stands for every handler of `Click`.
pub fn markup_kinds_for(id: &str, language: &str) -> &'static [&'static str] {
    match (id, language) {
        ("xaml", "csharp") => &["xaml"],
        ("razor", "csharp") => &["razor"],
        ("godot-signal", "csharp") => &["tscn"],
        _ => NONE,
    }
}

/// A method the runtime invokes by exact name *and* parameter list.
///
/// Java serialization finds `readObject(ObjectInputStream)` reflectively
/// on the class being (de)serialized; a `readObject(String path)` helper
/// is not one and must stay reportable. `params` are the parameter type
/// names in order (last segment, generics stripped); empty means the
/// method takes none.
#[derive(Debug)]
pub struct SignatureMethod {
    pub name: &'static str,
    pub params: &'static [&'static str],
}

/// The signature-keyed hooks of one built-in rule.
pub fn signature_methods_for(id: &str, language: &str) -> &'static [SignatureMethod] {
    match (id, language) {
        ("java-serialization", "java") => &[
            SignatureMethod {
                name: "readObject",
                params: &["ObjectInputStream"],
            },
            SignatureMethod {
                name: "writeObject",
                params: &["ObjectOutputStream"],
            },
            SignatureMethod {
                name: "readObjectNoData",
                params: NONE,
            },
            SignatureMethod {
                name: "readResolve",
                params: NONE,
            },
            SignatureMethod {
                name: "writeReplace",
                params: NONE,
            },
        ],
        _ => &[],
    }
}

/// Rules whose exact method names match case-sensitively. The default is
/// case-insensitive so one list covers Go's `GET` and Rails' `get`; a
/// macro-named C++ test case (`TEST`) or a fixed C symbol must not also
/// take a `test` helper. Python looks methods up by their exact name, so
/// its name-convention rules compare exactly too: discord.py's extension
/// `setup` is not unittest's `setUp`. Every Go rule is case-sensitive: the
/// case of a Go name's first letter is its export bit, and a framework
/// reaches a method only through an interface, which only an exported
/// method can satisfy, so bubbletea's `Init` is never a package's `init`
/// and a lowercase `read` helper never terraform's `Read`. (Registrar
/// verbs are not method names and keep their case-insensitive compare.)
pub fn methods_case_sensitive(id: &str, language: &str) -> bool {
    matches!(
        (id, language),
        ("gtest", "cpp")
            | ("gtest-fixture", "cpp")
            | ("libfuzzer", "c" | "cpp")
            | (_, "go")
            | ("boost-test", "cpp")
            // `setup`/`loop`, never a Unity `setUp`.
            | ("arduino", "c" | "cpp")
            // Shell functions are called by their exact names.
            | ("shunit2" | "makepkg" | "mkinitcpio", "bash")
            | ("moose-lifecycle", "perl")
    ) || (language == "python"
        && matches!(
            id,
            "blender-addon"
                | "blender-addon-register"
                | "qt"
                | "textual"
                | "home-assistant"
                | "home-assistant-entity"
                | "django-lifecycle"
                | "drf-serializers"
                | "odoo-model"
                | "graphene"
                | "discord-py"
                | "discord-py-extension"
        ))
}

/// File-routed frameworks: the directory whose files ARE the routes. A
/// method-name entry of such a rule counts only in a file under that
/// directory, and its route is the file's path below it, without the
/// extension (`routes/users/[id].dart` serves `/users/[id]`, an `index`
/// file its directory). Every dart_frog handler is a top-level
/// `onRequest`, so without the path they would all share one node.
pub fn path_route_dir(id: &str, language: &str) -> Option<&'static str> {
    match (id, language) {
        ("dart-frog", "dart") => Some("routes"),
        _ => None,
    }
}

/// The `methods` token that names the constructor of a class a
/// `base_types` row matched, whatever the language calls it: an Akka.NET
/// `ReceiveActor` registers its handlers in its constructor and a
/// FluentValidation validator declares its rules there, and the DI
/// container or actor system, not the tree, constructs both.
pub const CONSTRUCTOR_METHOD: &str = "<init>";

/// A parameter-type entry shape: a callable whose LAST parameter has the
/// type `type_name` (last segment, generics stripped) and which takes at
/// most `max_params` parameters is an entry, whatever its name. AWS
/// Lambda's .NET runtime invokes a handler named only in deployment
/// configuration, and its one structural mark is the trailing
/// `ILambdaContext`; a helper that receives the context (`Log(ctx, m)`)
/// takes it first, or takes more.
#[derive(Debug)]
pub struct ParameterTypeEntry {
    pub type_name: &'static str,
    pub max_params: usize,
}

/// The parameter-type entry shapes of one built-in rule.
pub fn parameter_types_for(id: &str, language: &str) -> &'static [ParameterTypeEntry] {
    match (id, language) {
        ("aws-lambda", "csharp" | "fsharp") => &[ParameterTypeEntry {
            type_name: "ILambdaContext",
            max_params: 2,
        }],
        _ => &[],
    }
}

/// A member of an attributed container that the container's rule does
/// not enter: zbus `#[zbus(signal)]` methods are emitters user code calls,
/// not handlers the bus calls.
pub fn container_member_skipped(id: &str, language: &str, attribute: &str) -> bool {
    let a: String = attribute.chars().filter(|c| !c.is_whitespace()).collect();
    match (id, language) {
        ("zbus", "rust") => {
            a.contains("zbus(signal") || a.contains("dbus_interface(signal")
        }
        _ => false,
    }
}

/// Rules whose `methods` name free functions only: Arduino's core calls
/// the sketch's own `setup()`/`loop()`, and a class's `GPS::setup()` is
/// not one, however the name reads.
pub fn methods_are_free_functions(id: &str, language: &str) -> bool {
    matches!((id, language), ("arduino", "c" | "cpp"))
}

/// Test rules whose base type is too general to stand alone. QtTest's
/// test classes derive plain `QObject`, so a `QObject` subclass is a test
/// class only in a test file or one that includes QTest; elsewhere its
/// `init()` is production code.
pub fn base_types_need_harness_file(id: &str, language: &str) -> bool {
    matches!((id, language), ("qtest", "cpp"))
}

/// The files a rule's method and base-type matchers read, as path
/// markers compared like `detect_paths` (segment suffixes, a trailing `/`
/// for a directory anywhere in the path, `*` within one segment). Empty
/// means every file of the language.
///
/// For hosts that call a fixed name only in a file of a fixed place: a
/// Neovim plugin's `setup` in `lua/<name>/init.lua`, an APISIX plugin's
/// phase functions in `apisix/plugins/<name>.lua`, makepkg's `build` in a
/// `PKGBUILD`. Matching the name anywhere in the tree would root every
/// `setup`, `access` or `build` of the project. A property of the host's
/// loader, not a rule a user should be authoring, so kept out of
/// [`FrameworkRule`] like [`detect_calls_for`].
pub fn method_paths_for(id: &str, language: &str) -> &'static [&'static str] {
    match (id, language) {
        ("kong", "lua") => &["kong/plugins/*/handler.lua"],
        ("apisix-plugin", "lua") => {
            &["apisix/plugins/*.lua", "apisix/stream/plugins/*.lua"]
        }
        ("neovim-plugin", "lua") => &["lua/*/init.lua", "lua/*/health.lua", "lua/*.lua"],
        ("bats", "bash") => &["*.bats", "setup_suite.bash"],
        ("makepkg", "bash") => &["PKGBUILD", "*.install"],
        ("chocolatey-au", "powershell") => &["update.ps1", "*_update.ps1"],
        ("franklin", "julia") => &["utils.jl"],
        _ => NONE,
    }
}

/// Languages whose bare base-class name resolves lexically, through the
/// enclosing namespaces only (Ruby constant lookup): the base-chain walk
/// never reads it as a same-named type of an unrelated namespace.
pub const LEXICAL_CONSTANT_LANGS: &[&str] = &["ruby"];

/// Rules whose base-type matcher takes every public instance member of a
/// matching class, on top of the hooks `methods` names: the host calls
/// any public method by name from outside the code (a Livewire
/// component's `wire:click="save"` from a Blade template, a Nextcloud
/// controller's endpoint from `appinfo/routes.php`), while private and
/// protected helpers, static members and magic `__x` methods stay
/// reportable. With no `methods`, only the public members.
pub fn public_members_are_entries(id: &str, language: &str) -> bool {
    matches!((id, language), ("livewire" | "nextcloud", "php"))
}

/// Call names that alone prove a framework is present, for ecosystems
/// with no import records. Returned separately from [`FrameworkRule`]
/// because it is a detection input, not a matcher, and a user-authored
/// rule has no business declaring one.
pub fn detect_calls_for(id: &str, language: &str) -> &'static [&'static str] {
    SPECS
        .iter()
        .find(|s| s.id == id && s.language == language)
        .map(|s| s.detect_calls)
        .unwrap_or(NONE)
}

/// Why a built-in rule cannot enumerate entries, if it cannot.
pub fn gap_for(id: &str, language: &str) -> &'static str {
    SPECS
        .iter()
        .find(|s| s.id == id && s.language == language)
        .map(|s| s.gap)
        .unwrap_or("")
}

/// Languages in which cgg has at least one framework rule. Everything
/// else is disclosed in the coverage table's "no rules" line rather than
/// silently producing zero entries.
pub fn languages_with_rules() -> Vec<&'static str> {
    let mut v: Vec<&'static str> = SPECS.iter().map(|s| s.language).collect();
    v.sort_unstable();
    v.dedup();
    v
}

/// Every registrar verb any rule can match, lowercased and deduplicated.
///
/// Exists so the *extraction* layer can skip calls no rule could ever
/// use. Argument capture is otherwise paid on every call expression in
/// the tree, and measured on TypeORM that doubled the run: thousands of
/// `describe('...', () => {})` blocks are shaped exactly like a route
/// registration and are not one.
///
/// Gating here loses nothing a built-in rule could have matched — the
/// list is their union. User-authored rules add their own verbs through
/// `cgg_lang::ExtractCtx`.
pub fn registrar_verbs() -> &'static [&'static str] {
    static VERBS: std::sync::OnceLock<Vec<&'static str>> = std::sync::OnceLock::new();
    VERBS.get_or_init(|| {
        let mut v: Vec<&'static str> = SPECS
            .iter()
            // A test harness's block verbs gate test files only.
            .filter(|s| s.kind != TrustKind::Test)
            .flat_map(|s| s.registrars.iter().copied())
            .collect();
        v.sort_unstable_by_key(|a| a.to_ascii_lowercase());
        v.dedup_by(|a, b| a.eq_ignore_ascii_case(b));
        v
    })
}

/// The registrar verbs of one language only.
///
/// The union above is a coarse gate: `Start` is a verb because Go's
/// aws-lambda rule registers it, and every Ruby, PHP and Python file was
/// paying an argument scan for its own `start` calls as a result. A verb
/// can only ever match a rule of its own language, so narrowing the gate
/// loses nothing and removes that cross-language cost — the effect grows
/// with the table, which is now several hundred rules.
///
/// Returns `None` for a language with no registrar-bearing rule at all,
/// which lets the caller skip the lookup entirely.
pub fn registrar_verbs_for(language: &str) -> Option<&'static [&'static str]> {
    static BY_LANG: std::sync::OnceLock<
        std::collections::HashMap<&'static str, Vec<&'static str>>,
    > = std::sync::OnceLock::new();
    BY_LANG
        .get_or_init(|| {
            let mut m: std::collections::HashMap<&'static str, Vec<&'static str>> =
                std::collections::HashMap::new();
            for s in SPECS {
                if s.registrars.is_empty() || s.kind == TrustKind::Test {
                    continue;
                }
                m.entry(s.language).or_default().extend(s.registrars);
            }
            for v in m.values_mut() {
                v.sort_unstable_by_key(|a| a.to_ascii_lowercase());
                v.dedup_by(|a, b| a.eq_ignore_ascii_case(b));
            }
            m
        })
        .get(language)
        .map(Vec::as_slice)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    #[test]
    fn every_rule_is_either_detectable_or_a_declared_gap() {
        for s in SPECS {
            let detectable = !s.detect.is_empty()
                || !s.detect_paths.is_empty()
                || !s.detect_calls.is_empty();
            // Three rules are keyed purely on a marker written on the
            // definition, which IS the evidence and needs no import
            // gate: CUDA's `__global__`, Solidity's `public`/`external`
            // visibility, and Rust's FFI export attributes. Listed
            // explicitly rather than inferred, so a new rule cannot skip
            // detection by accident — that gate is what stops a verb
            // like `get` matching every `cache.get` in a tree.
            // WS18 adds the marker-only test and export attributes
            // (`#[test]`, `[JSExport]`), RTIC's task attributes, and the
            // markup bindings read from a code-behind's sibling file.
            let marker_is_the_evidence = matches!(
                s.id,
                "cuda"
                    | "solidity-public"
                    | "ffi-export"
                    | "cargo-test"
                    | "cargo-bench"
                    | "rtic"
                    | "dotnet-ffi-export"
                    | "xaml"
                    | "razor"
                    // WS20: a fixed engine-called symbol, by its exact name.
                    | "libfuzzer"
                    // 0.14.0: language-level markers that need no import —
                    // Kotlin's `@JsExport`, Scala 3's `@main`, and
                    // ClojureScript's `^:export` / shadow-cljs reload hooks.
                    | "kotlin-js-export"
                    | "scala-main"
                    | "cljs-export"
                    | "shadow-cljs-hooks"
                    // 0.14.0: Kani's path-qualified harness attribute, and
                    // fixed solver-, hardware- and CMake-called names.
                    | "kani"
                    | "cmsis-vectors"
                    | "cmake-package-init"
                    | "abaqus-user-subroutine"
                    | "ansys-user-material"
                    | "lsdyna-user-material"
                    // Lean attributes are core syntax, needing no import.
                    | "lean-ffi"
                    | "lean-attributes"
                    // 0.14.0: LÖVE's owner-qualified callbacks (`love.load`)
                    // and mkinitcpio's `run_*hook` functions.
                    | "love2d"
                    | "mkinitcpio"
            );
            assert!(
                detectable || marker_is_the_evidence,
                "{}/{} can never fire: no detect, no paths, no calls",
                s.language,
                s.id
            );
        }
    }

    #[test]
    fn a_rule_with_no_matchers_must_declare_why() {
        // Silence is the failure mode this whole feature exists to
        // avoid. A framework cgg lists but cannot enumerate has to say
        // so, or the coverage table reads as complete when it is not.
        for s in SPECS {
            // Mirrors `FrameworkRule::has_matchers`, including the
            // matchers that live outside the struct — a rule that
            // enumerates via one of those is not a gap.
            let has_matchers = !s.attributes.is_empty()
                || !s.registrars.is_empty()
                || !s.base_types.is_empty()
                || !s.methods.is_empty()
                || !visibility_entries_for(s.id, s.language).is_empty()
                || !self_module_markers_for(s.id, s.language).is_empty()
                || !member_sources_for(s.id, s.language).is_empty()
                || !signature_methods_for(s.id, s.language).is_empty()
                || !container_attributes_for(s.id, s.language).is_empty()
                || !markup_kinds_for(s.id, s.language).is_empty();
            assert!(
                has_matchers || !s.gap.is_empty(),
                "{}/{} has no matchers and no stated gap",
                s.language,
                s.id
            );
        }
    }

    #[test]
    fn ids_are_unique_per_language() {
        let mut seen: HashSet<(&str, &str)> = HashSet::new();
        for s in SPECS {
            assert!(
                seen.insert((s.language, s.id)),
                "duplicate rule {}/{}",
                s.language,
                s.id
            );
        }
    }

    #[test]
    fn registrar_verbs_covers_every_rules_vocabulary() {
        let verbs = registrar_verbs();
        // A test harness's block verbs are gated per test file instead
        // (`cgg_lang::ExtractCtx::for_test_file`), never by this union.
        for s in SPECS.iter().filter(|s| s.kind != TrustKind::Test) {
            for r in s.registrars {
                assert!(
                    verbs.iter().any(|v| v.eq_ignore_ascii_case(r)),
                    "{}/{} registrar `{r}` is not in the extraction gate — \
                     the rule can never fire",
                    s.language,
                    s.id
                );
            }
        }
    }

    #[test]
    fn builtin_expands_every_spec() {
        assert_eq!(builtin().len(), SPECS.len());
        let flask = builtin()
            .into_iter()
            .find(|r| r.id == "flask")
            .expect("flask rule");
        assert_eq!(flask.kind, TrustKind::Network);
        assert!(flask.has_matchers());
    }

    #[test]
    fn the_inventorys_web_frameworks_are_all_present() {
        // §4's inventory is the contract. If a row is dropped from the
        // table, the coverage claim in the README stops being true.
        let ids: HashSet<&str> = SPECS.iter().map(|s| s.id).collect();
        for want in [
            "fastapi",
            "flask",
            "django",
            "celery",
            "torch",
            "express",
            "nestjs",
            "spring",
            "jakarta-rs",
            "micronaut",
            "akka",
            "gin",
            "echo",
            "fiber",
            "chi",
            "net-http",
            "temporal",
            "rails",
            "sinatra",
            "grape",
            "sidekiq",
            "laravel",
            "symfony",
            "wordpress",
            "codeigniter",
            "aspnet-mvc",
            "aspnet-minimal",
            "quartz",
            "masstransit",
            "axum",
            "actix-web",
            "rocket",
            "cuda",
        ] {
            assert!(
                ids.contains(want),
                "inventory framework `{want}` is missing"
            );
        }
    }

    #[test]
    fn bucket_d_lifecycle_rules_do_not_mint_nodes() {
        // §8: an entry node per bucket-D method is visually useless.
        for s in SPECS {
            if s.kind == TrustKind::Lifecycle && !s.base_types.is_empty() {
                assert!(
                    !s.node,
                    "{}/{} would fan out a lifecycle node",
                    s.language, s.id
                );
            }
        }
    }
}
